-- CampBuddy — Wasser und Aussicht für die Region CH.
-- Ausführen: Supabase-Projekt -> SQL Editor -> Inhalt einfügen -> Run.
-- Setzt Migration 0010 voraus.
--
-- 23753 Objekte aus OpenStreetMap (ODbL): 15009 drinking_water, 2339 lake, 565 spring, 4351 viewpoint, 1489 waterfall.
--
-- Eine Trinkwasser-Markierung in OSM ist die Angabe einer Mapperin, keine
-- Laboranalyse. Die Infokarte sagt das auch so.
-- Teil 4 von 6.

begin;
on conflict (id) do update set region = excluded.region, type = excluded.type, name = excluded.name, benannt = excluded.benannt, lat = excluded.lat, lng = excluded.lng, elevation = excluded.elevation, source_url = excluded.source_url, updated_at = now();
commit;
